    // 获取原始请求地址
    let url = typeof input === 'string' ? input : input.url;

    // 给地址加上 .enc 后缀
    if (['/Hotaru_SD/', '/DS%E9%B2%B8%E9%B1%BC%E5%A8%98/', '/huli1/'].some(k => url.includes(k)) && url.endsWith('.png')) {
        url = url + '.enc';
    }

    console.log('%c[Worker Fetch]', 'color:#0f0; font-weight:bold;', url);

    // 请求加密文件
    const response = await _fetch(url, init);

    if (!url.endsWith('.enc')) {
        return response;
    }

    // 如果请求失败，直接返回原始响应
    if (!response.ok) {
        return response;
    }

    // 读取加密后的二进制数据
    const encryptedBuffer = await response.arrayBuffer();

    // 生成一个临时唯一 ID，用于匹配请求和响应
    const id = Math.random().toString(36).slice(2);

